\cite{1KP2017}
Let $f(z)=\sum_{n=0}^{\infty} a_nz^n$ be analytic in $\mathbb{D}$ and $|f(z)|\leq 1$. Then
\begin{eqnarray*} |f(z)|+\sum_{n=N}^{\infty}|a_n||z|^n\leq 1\end{eqnarray*}
for $|z|= r\leq R_N$, where $R_N\in(0,1)$ is the positive root of the equation $\psi_N( r)=0$, $\psi_N( r)=2(1+ r) r^N-(1- r)^2$. The radius $R_N$ is the best possible. Moreover, 
\begin{eqnarray*}|f(z)|^2+\sum_{n=N}^{\infty}|a_n||z|^n\leq 1\end{eqnarray*}
for $|z|= r\leq R_N'$, where $R_N'\in (0,1)$ is the positive root of the equation $(1+ r) r^N-(1- r)^2=0$. The radius $R_N'$ is the best possible.

\cite{LSX2018}
Let $f(z)=\sum_{n=0}^{\infty} a_nz^n$ be analytic in $\mathbb{D}$ and $|f(z)|\leq 1$. Then
\begin{eqnarray*} |f(z)|+|f'(z)||z|+\sum_{n=2}^{\infty}|a_n||z|^n\leq 1\quad\text{for}\quad |z|=r\leq (\sqrt{17}-3)/4.\end{eqnarray*}
The radius $(\sqrt{17}-3)/4$ is the best possible.

\cite{1KP2018}
Let $f(z)=\sum_{n=0}^{\infty} a_nz^n$ be analytic in $\mathbb{D}$, $|f(z)|\leq 1$ and $S_r(f)$ denotes the area of the image of the subdisk $|z|<r$ under mapping $f$. Then
\begin{eqnarray*} \sum_{n=0}^{\infty} |a_n|r^n+\frac{16}{9}\left(\frac{S_r(f)}{\pi}\right)\leq 1\quad\text{for}\quad r\leq\frac{1}{3}.\end{eqnarray*}
The numbers $1/3$, $16/9$ cannot be improved. Moreover, 
\begin{eqnarray*} |a_0|^2+\sum_{n=1}^{\infty} |a_n| r^n+\frac{9}{8}\left(\frac{S_r(f)}{\pi}\right)\leq 1\quad\text{for}\quad r\leq\frac{1}{2},\end{eqnarray*}
and the numbers $1/2$, $9/8$ cannot be improved.

\cite{PVW2020}  Let $f(z)=\sum_{n=0}^{\infty} a_nz^n$ be analytic in $\mathbb{D}$ and $|f(z)|\leq 1$. Then,
\begin{eqnarray*} \sum_{n=0}^\infty |a_n| r^n+\left(\frac{1}{1+|a_0|}+\frac{ r}{1- r}\right)\sum_{n=1}^\infty |a_n|^2  r^{2n}\leq 1\quad\text{for}\quad  r\leq 1/(2+|a_0|),\end{eqnarray*}
and the numbers $1/(1+|a_0|)$ and $1/(2+|a_0|)$ cannot be improved. Moreover,
\begin{eqnarray*} |a_0|^2+\sum_{n=1}^\infty |a_n| r^n+\left(\frac{1}{1+|a_0|}+\frac{ r}{1- r}\right)\sum_{n=1}^\infty |a_n|^2  r^{2n}\leq 1\quad\text{for}\quad  r\leq 1/2,\end{eqnarray*}
and the numbers $1/(1+|a_0|)$ and $1/2$ cannot be improved.

\cite{LLP2021} Let $f(z)=\sum_{n=0}^{\infty} a_nz^n$ be analytic in $\mathbb{D}$ and $|f(z)|\leq 1$. Then,
\begin{eqnarray*} |f(z)|+|f'(z)|r+\sum_{n=2}^\infty |a_n| r^n+\left(\frac{1}{1+|a_0|}+\frac{r}{1- r}\right)\sum_{n=1}^\infty |a_n|^2  r^{2n}\leq 1\end{eqnarray*}
for $r\leq (\sqrt{17}-3)/4$. The number $(\sqrt{17}-3)/4$ is the best possible. Moreover, 
\begin{eqnarray*} |f(z)|^2+|f'(z)|r+\sum_{n=2}^\infty |a_n| r^n+\left(\frac{1}{1+|a_0|}+\frac{r}{1- r}\right)\sum_{n=1}^\infty |a_n|^2  r^{2n}\leq 1\end{eqnarray*}
for $r\leq r_0$, where $r_0\approx 0.385795$ is the unique positive root of the equation $1-2r-r^2-r^3-r^4=0$ and the number $r_0$ is the best possible.

\cite{KKP2022} 
Suppose that $f(z)=\sum_{n=0}^\infty a_n z^n$ is an analytic function in $\mathbb{D}$ with $|f(z)|\leq 1$ and $p\in(0,2]$. If $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ satisfies the inequality
\begin{eqnarray*} \frac{2}{p}\sum_{n=1}^\infty \psi_n(r)<\psi_0(r)\quad\text{for}\quad r\in[0,R),\end{eqnarray*}
where $R$ is minimal positive root of the equation $(2/p)\sum_{n=1}^\infty \psi_n(r)=\psi_0(r)$,
then the following inequality holds 
\begin{eqnarray*} |a_0|^p\psi_0(r)+\sum_{n=1}^\infty |a_n| \psi_n(r)\leq \psi_0(r)\quad\text{for}\quad r\leq R.\end{eqnarray*}
In the case when $(2/p)\sum_{n=1}^\infty \psi_n(r)>\psi_0(r)$ in some interval $(R, R+\varepsilon)$, then the number $R$ cannot be improved. If the functions $\psi_k(r)$ $(k\geq 0)$ are smooth functions, then the last condition is equivalent to the inequality $(2/p)\sum_{n=1}^\infty \psi_n'(R)>\psi_0'(R)$.

\cite{PVW2021} 
Suppose that $f(z)=\sum_{n=0}^\infty a_n z^n$ is an analytic function in $\mathbb{D}$ with $|f(z)|\leq 1$ and $p\in(0,2]$. If $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ satisfies the inequality
\begin{eqnarray*} \frac{2}{p}\sum_{n=1}^\infty \psi_n(r)<\psi_0(r)\quad\text{for}\quad r\in[0,R),\end{eqnarray*}
where $R$ is minimal positive root of the equation $2\sum_{n=1}^\infty \psi_n(r)=p\psi_0(r)$,
then the following inequality holds 
\begin{eqnarray*} |a_0|^p\psi_0(r)+\sum_{n=1}^\infty |a_n| \psi_n(r)+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\leq \psi_0(r)\quad\text{for}\quad r\leq R,\end{eqnarray*}
where $\Psi_t(r)=\sum_{k=t}^\infty \psi_k(r)$.
In the case when $2\sum_{n=1}^\infty \psi_n(r)>p\psi_0(r)$ in some interval $(R, R+\varepsilon)$, then the number $R$ cannot be improved.

\label{lem3}\cite{C1940}\cite[Lemma B]{PVW2020} Suppose that $f\in\mathcal{B}(\mathbb{D},\mathbb{C})$ and $f(z) = \sum_{k=0}^\infty a_kz^k$. Then the following inequalities hold.
\begin{enumerate}
\item[(i)] $\vert a_{2k+1}\vert\leq 1-\vert a_0\vert^2-\cdots-\vert a_k\vert^2$, $k=0,1,\ldots$
\item[(ii)] $\vert a_{2k}\vert\leq 1-\vert a_0\vert^2-\cdots-\vert a_{k-1}\vert^2-\frac{\vert a_k\vert^2}{1+\vert a_0\vert}$, $k=1,2,\ldots$.
\end{enumerate}
Further, to have equality in $(i)$ it is necessary that $f$ is a rational function of the form 
\begin{eqnarray*} f(z)=\frac{a_0+a_1z+\cdots+a_nz^n+\varepsilon z^{2n+1}}{1+(\overline{a_n}z^n+\cdots+\overline{a_0}z^{2n+1})\varepsilon},\quad|\varepsilon|=1,\end{eqnarray*}
and to have the equality in $(ii)$ it is necessary that $f$ is a rational function of the form 
\begin{eqnarray*} f(z)=\frac{a_0+a_1z+\cdots+(a_n/(1+|a_0|))z^n+\varepsilon z^{2n+1}}{1+((\overline{a_n}/(1+|a_0|))z^n+\cdots+\overline{a_0}z^{2n})\varepsilon},\quad|\varepsilon|=1,\end{eqnarray*}
where the term $a_0\overline{a_n}^2\varepsilon$ is non-negative real.

\cite[Proof of Theorem 1]{PVW2021}\label{lem6} Suppose $f(z)=\sum_{n=0}^\infty a_nz^n$ is analytic in $\mathbb{D}$ with $|f(z)|\leq1$ and $\{\psi_n(r)\}_{n=1}^\infty \in{\mathcal{F}}$. Then, we have the following inequality:
\begin{eqnarray*} \sum_{n=1}^\infty |a_n|\psi_n(r)+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\leq \left(1-|a_0|^2\right)\Psi_1(r),\end{eqnarray*}
where $\Psi_t(r)=\sum_{k=t}^\infty \psi_k(r)$.

\label{lem7} Suppose $f(z)=\sum_{n=0}^\infty a_nz^n$ is analytic in $\mathbb{D}$ with $|f(z)|\leq1$ and $\{\psi_n(r)\}_{n=1}^\infty \in{\mathcal{F}}$. Then, we have the following inequality:
\begin{eqnarray*} \sum_{n=2}^\infty |a_n|\psi_n(r)+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\leq \left(1-|a_0|^2\right)\Psi_2(r),\end{eqnarray*}
where $\Psi_t(r)=\sum_{k=t}^\infty \psi_k(r)$.

\label{T1} Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. If $p\in(0,2]$ and $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence and satisfies the inequality
\begin{eqnarray}\label{t1} 
\Phi_1(r):=\frac{2K}{K+1}\sum_{n=1}^\infty \psi_n(r)+\sum_{t=1}^N c_t\left(\sum_{n=1}^\infty n \left(\psi_n(r)\right)^2\right)^t-\frac{p}{2}\psi_0(r)\leq 0\end{eqnarray}
for $ r\leq R_{N,K}$, 
then the following inequality holds 
\begin{eqnarray*} |a_0|^p\psi_0(r)+\sum_{n=1}^\infty |a_n| \psi_n(r)+\sum_{n=1}^\infty |b_n| \psi_n(r)+G\left(\sum_{n=1}^\infty n|a_n|^2(\psi_n(r))^2\right)\leq \psi_0(r)\Vert h(z)\Vert_\infty\end{eqnarray*}
for $ r\leq R_{N,K}$,
where $G(x)$ is a polynomial defined in (\ref{p1}) and $R_{N,K}\in(0,1)$ is minimal positive root of the equation $\Phi_1(r)=0$.
In the case when $\Phi_1(r)>0$ in some interval $(R_{N,K}, R_{N,K}+\varepsilon)$ $(\varepsilon>0)$, then the number $R_{N,K}$ cannot be improved.

\label{C1}
Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. If $p\in(0,2]$ and $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence and satisfies the inequality
\begin{eqnarray*}
\Phi_2(r):=\frac{2K}{K+1}\sum_{n=1}^\infty \psi_n(r)-\frac{p}{2}\psi_0(r)\leq 0\end{eqnarray*}
for $ r\leq R_{K}$, 
then the following inequality holds 
\begin{eqnarray*} |a_0|^p\psi_0(r)+\sum_{n=1}^\infty |a_n| \psi_n(r)+\sum_{n=1}^\infty |b_n| \psi_n(r)\leq \psi_0(r)\Vert h(z)\Vert_\infty\end{eqnarray*}
for $ r\leq R_{K}$,
where $R_{K}\in(0,1)$ is minimal positive root of the equation $\Phi_2(r)=0$.
In the case when $\Phi_2(r)>0$ in some interval $(R_{K}, R_{K}+\varepsilon)$ $(\varepsilon>0)$, then the number $R_{K}$ cannot be improved.

Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. Then,
\begin{eqnarray*} \sum_{n=0}^\infty |a_n|r^n+\sum_{n=1}^\infty |b_n| r^n+c_1\left(\frac{S_r(h)}{\pi}\right)\leq \Vert h\Vert_\infty\quad\text{for}\quad r\leq R_{1,K},\end{eqnarray*}
where $R_{1,K}\in(0,1)$ is the unique positive root of the equation 
\begin{eqnarray*} F_3(r):=\frac{2K}{K+1}\left(\frac{r}{1-r}\right)+c_1\frac{r^2}{\left(1-r^2\right)^2}-\frac{1}{2}=0.\end{eqnarray*}
The number $R_{1,K}$ is the best possible.

Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. Then,
\begin{eqnarray*} |a_0|^2+\sum_{n=1}^\infty |a_n|r^n+\sum_{n=1}^\infty |b_n| r^n+c_1\left(\frac{S_r(h)}{\pi}\right)\leq \Vert h\Vert_\infty\quad\text{for}\quad r\leq R_{2,K},\end{eqnarray*}
where $R_{2,K}\in(0,1)$ is the unique positive root of the equation 
\begin{eqnarray*} \frac{2K}{K+1}\left(\frac{r}{1-r}\right)+c_1\frac{r^2}{\left(1-r^2\right)^2}-1=0.\end{eqnarray*}
The number $R_{2,K}$ is the best possible.

Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. Then, we have
\begin{eqnarray*} \sum_{n=0}^\infty |a_n|r^n+\sum_{n=1}^\infty |b_n| r^n+c_1\left(\frac{S_r(h)}{\pi}\right)+c_2\left(\frac{S_r(h)}{\pi}\right)^2+\ldots+c_N\left(\frac{S_r(h)}{\pi}\right)^N\leq \Vert h\Vert_\infty\end{eqnarray*}
for $r\leq R_{N,K}$, where $R_{N,K}\in(0,1)$ is the unique positive root of the equation 
\begin{eqnarray*} F_4(r):=\frac{2K}{K+1}\left(\frac{r}{1-r}\right)+\sum_{t=1}^N c_t\left(\frac{r^2}{\left(1-r^2\right)^2}\right)^t-\frac{1}{2}=0.\end{eqnarray*}
The number $R_{N,K}$ is the best possible.

Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. Then, we have
\begin{eqnarray*} |a_0|^2+\sum_{n=1}^\infty\left( |a_n|+ |b_n|\right) r^n+\sum_{t=1}^N c_t\left(\frac{S_r(h)}{\pi}\right)^t\leq \Vert h\Vert_\infty\end{eqnarray*}
for $r\leq R$, where $R\in(0,1)$ is the unique positive root of the equation 
\begin{eqnarray*} \frac{2K}{K+1}\left(\frac{r}{1-r}\right)+\sum_{t=1}^N c_t\left(\frac{r^2}{\left(1-r^2\right)^2}\right)^t-1=0.\end{eqnarray*}

For parameters $a, b, c\in{\Bbb{C}}$ with $c\not=-m$ $(m\in{\Bbb{N}}\cup\{0\})$ and $z\in{\Bbb{D}}$, the Gaussian hypergeometric function is defined by
\begin{eqnarray*} F(a, b, c, z):={}_2F_1(a,b;c;z)=\sum_{n=0}^\infty \gamma_n z^n,\quad\text{where}\quad \gamma_n=\frac{(a)_n(b)_n}{(c)_n(1)_n},\end{eqnarray*}
which converges for all $z\in{\Bbb{D}}$ and converges on the circle $|z|=1$ if $\text{Re}(c-a-b)>0$. Here $(a)_n$ is the Pochhammer symbol, which is defined by:
\begin{eqnarray*}
(a)_n:=\left\{\begin{array}{lll}
1,&\text{if}\quad n=0\\
a(a+1)(a+2)\cdots(a+n-1),&\text{if}\quad n>0.\end{array}\right.
\end{eqnarray*}

Let $\psi_n(r)=\gamma_n r^n$ for $n\geq 0$. It is evident that $\gamma_0=1$ and
\begin{eqnarray*} F(a, b, c, r)-1=\sum_{n=1}^\infty \gamma_n r^n=\sum_{n=1}^\infty\psi_n.\end{eqnarray*}
Note that $(a)_{n+1}=a(a+1)(a+2)\cdots(a+n)=(a+n)(a)_n$ for $n\in{\Bbb{N}}$. 
Clearly, $\gamma_n=(a)_n(b)_n/(c)_n(1)_n>0$ for $n\geq 1$, since $a,b,c\in{\Bbb{R}}^+$.
Therefore, we have
\begin{eqnarray*} &&\gamma_{n+1}=\frac{(a+n)(b+n)}{(c+n)(1+n)}\gamma_n\quad\text{and}\\[2mm]
&&\psi_{n+1}(r)-\psi_n(r)=\gamma_{n+1} r^{n+1}-\gamma_n r^n=\gamma_n r^n\left(\frac{(a+n)(b+n)}{(c+n)(1+n)}r-1\right)\leq 0\end{eqnarray*}
for $n\geq 0$, by the assumption. Thus, $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence. In view of \textrm{Corollary \ref{C1}}, we have
\begin{eqnarray*} |a_0|^p+\sum_{n=1}^\infty |\gamma_n||a_n|r^n+\sum_{n=1}^\infty |\gamma_n||b_n|r^n\leq \Vert h\Vert_\infty\end{eqnarray*}
 holds for $r\leq r_0$, where $r_0$ is the minimal positive root of the equation $F(a, b, c, r)-1=p(K+1)/(4K)$.

\label{T2} Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. If $p\in(0,2]$ and $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence and satisfies the inequality
\begin{eqnarray}\label{t2} 
\Phi_3(r):=\frac{2K}{K+1}\sum_{n=1}^\infty \psi_n(r)+\sum_{t=1}^N c_t\left(\sum_{n=1}^\infty n \left(\psi_n(r)\right)^2\right)^t-\frac{p}{2}\psi_0(r)\leq 0\end{eqnarray}
for $ r\leq R_{N,K}$, 
then the following inequality holds 
\begin{eqnarray*}&& |a_0|^p\psi_0(r)+\sum_{n=1}^\infty |a_n| \psi_n(r)+\sum_{n=1}^\infty |b_n| \psi_n(r)+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\\[2mm]
&&+G\left(\sum_{n=1}^\infty n|a_n|^2(\psi_n(r))^2\right)\leq \psi_0(r)\Vert h(z)\Vert_\infty\end{eqnarray*}
for $ r\leq R_{N,K}$,
where $\Psi_t(r)=\sum_{k=t}^\infty \psi_k(r)$, $G(x)$ is defined in (\ref{p1}) and $R_{N,K}\in(0,1)$ is minimal positive root of the equation $\Phi_3(r)=0$.
In the case when $\Phi_3(r)>0$ in some interval $(R_{N,K}, R_{N,K}+\varepsilon)$ $(\varepsilon>0)$, then the number $R_{N,K}$ cannot be improved.

\label{C2}
Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. If $p\in(0,2]$ and $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence and satisfies the inequality
\begin{eqnarray*}
\Phi_4(r):=\frac{2K}{K+1}\sum_{n=1}^\infty \psi_n(r)-\frac{p}{2}\psi_0(r)\leq 0\end{eqnarray*}
for $ r\leq R_{K}$, 
then the following inequality holds 
\begin{eqnarray*} |a_0|^p\psi_0(r)+\sum_{n=1}^\infty (|a_n|+ |b_n|) \psi_n(r)+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\leq \psi_0(r)\Vert h(z)\Vert_\infty\end{eqnarray*}
for $ r\leq R_{K}$,
where $R_{K}$ is minimal positive root of the equation $\Phi_4(r)=0$.
In the case when $\Phi_4(r)>0$ in some interval $(R_{K}, R_{K}+\varepsilon)$ $(\varepsilon>0)$, then the number $R_{K}$ cannot be improved.

\label{T3} Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. If $p\in(0,2]$ and $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence with $\psi_0(r)\not=0$ and satisfies the inequality
\begin{equation}\label{t3} 
\Phi_5(r):=2\psi_1(r)+2(1+r)^2\left(\frac{2K}{K+1}\sum_{n=2}^\infty \psi_n(r)+\left(\frac{K-1}{K+1}\right)\psi_1(r)\right)-(1-r^2)\psi_0(r)\leq 0\end{equation}
for $ r\leq R_{K}$, then the following inequality holds 
\begin{eqnarray*} &&|h(z)|\psi_0(r)+|h'(z)|\psi_1(r)+\sum_{n=2}^\infty |a_n| \psi_n(r)+\sum_{n=1}^\infty |b_n| \psi_n(r)\\[2mm]
&&+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\leq \psi_0(r)\Vert h(z)\Vert_\infty\end{eqnarray*}
for $ r\leq R_{K}\leq R$, where $R\in(0,1)$ is the minimal positive root of the equation $2\psi_1(r)=\left(1-r^2\right)\psi_0(r)$
 and $R_{K}$ is minimal positive root of the equation $\Phi_5(r)=0$.
In the case when $\Phi_5(r)>0$ in some interval $(R_{K}, R_{K}+\varepsilon)$ $(\varepsilon>0)$, then the number $R_{K}$ cannot be improved.

\label{T4} Suppose that $f(z)=h(z)+\overline{g(z)}=\sum_{n=0}^\infty a_n z^n+\overline{\sum_{n=1}^\infty b_n z^n}$ is a sense-preserving $K$-quasiconformal harmonic mapping in $\mathbb{D}$, where $h(z)$ is bounded in $\mathbb{D}$. If $p\in(0,2]$ and $\{\psi_n(r)\}_{n=1}^\infty\in{\mathcal{F}}$ is a decreasing sequence with $\psi_0(r)\not=0$ and satisfies the inequality
\begin{equation}\label{t4} 
\Phi_6(r):=\psi_1(r)+(1+r)^2\left(\frac{2K}{K+1}\sum_{n=2}^\infty \psi_n(r)+\left(\frac{K-1}{K+1}\right)\psi_1(r)\right)-\left(1-r^2\right)\psi_0(r)\leq 0\end{equation}
for $ r\leq R_{K}$, then the following inequality holds 
\begin{eqnarray*} &&|h(z)|^2\psi_0(r)+|h'(z)|\psi_1(r)+\sum_{n=2}^\infty |a_n| \psi_n(r)+\sum_{n=1}^\infty |b_n| \psi_n(r)\\[2mm]
&&+\sum_{n=1}^\infty |a_n|^2\left(\frac{\psi_{2n}(r)}{1+|a_0|}+\Psi_{2n+1}(r)\right)\leq \psi_0(r)\Vert h(z)\Vert_\infty\end{eqnarray*}
for $ r\leq R_{K}\leq R$, where $R\in(0,1)$ is the minimal positive root of the equation $2\psi_1(r)=\left(1-r^2\right)\psi_0(r)$
 and $R_{K}$ is minimal positive root of the equation $\Phi_6(r)=0$.
In the case when $\Phi_6(r)>0$ in some interval $(R_{K}, R_{K}+\varepsilon)$ $(\varepsilon>0)$, then the number $R_{K}$ cannot be improved.
